<x-layouts.app title="Peta RTLH"><div class="pagehead"><div><div class="kicker">GIS</div><h1>Peta RTLH Kabupaten Cirebon</h1><p class="muted">Hanya data rumah yang telah dipublikasikan. Klik marker untuk melihat detail publik.</p></div></div><div class="toolbar"><input id="search" placeholder="Cari kode RTLH..."><select id="year"><option value="">Semua tahun</option>@for($y=date('Y');$y>=2020;$y--)<option value="{{ $y }}">{{ $y }}</option>@endfor</select><button class="btn" onclick="reloadMap()">Filter</button></div><div id="map" class="mapbox"></div>@push('head')<link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css">@endpush<script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script><script>
let map=L.map('map').setView([-6.73,108.55],10), layer=L.layerGroup().addTo(map);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© OpenStreetMap contributors'}).addTo(map);
async function reloadMap(){layer.clearLayers();let y=document.getElementById('year').value;let u='/api/v1/public/rtlh?per_page=500'+(y?'&year='+y:'');let r=await fetch(u),x=await r.json();(x.data?.data||x.data||[]).forEach(h=>{let c=h.coordinates;if(!c)return;let p=L.marker([c[1],c[0]]).addTo(layer);p.bindPopup('<b>'+h.house_code+'</b><br>'+((h.region&&h.region.name)||'')+'<br>Luas: '+(h.area_m2||'-')+' m²<br>Tahun: '+(h.survey_year||'-')+'<br><a href="/rtlh/'+h.id+'">Detail publik</a>');});}reloadMap();</script></x-layouts.app>
